from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class CounterValue(SchemaObject):
    start_time = SchemaField(name="startTime", not_null=True)
    value = SchemaField(name="value", not_null=True)

    def __init__(self, start_time, value):
        self.start_time = start_time
        self.value = value
        super(CounterValue, self).__init__()


class CounterValuePMV1(SchemaObject):
    id = SchemaField(name="id", not_null=True)
    dimension_dist_name = SchemaField(name="dimensionDistName", not_null=True)
    measurement_id = SchemaField(name="measurementId", not_null=True)
    values = SchemaField(name="values", not_null=True, klass=CounterValue, many=True)

    def __init__(self, id, dimension_dist_name, measurement_id, values):
        super(CounterValuePMV1, self).__init__()
        self.id = id
        self.dimension_dist_name = dimension_dist_name
        self.measurement_id = measurement_id
        self.values = values
